     % Convert characters to Morse Code
     for I = 1:length(phrase)
         char = upper(phrase(i));

         % Check if it's a digit or letter
         if isdigit(char)
             morseCode{end+1} = numToMorse{char};
         else
             morseCode{end+1} = morseMap{char};
         end

         % Add a space between characters
         if i ~= length(phrase)
             morseCode{end+1}(end+1) = ' ';
         end
     end

     % Remove trailing spaces
     morseCode{:} = morseCode{:}(1:end-1);
 end
 ```

 This function takes a `phrase` as input, converts it to Morse Code using the `morseMap` and `numToMorse` tables, and returns the resulting `morseCode` as a cell array. The function also handles the conversion of digits by using the `numToMorse` table. Note that the Morse Code sequences are stored as strings with spaces between them, which allows us to easily concatenate them later on.

