Firstly, let's install the Accord.NET library by running the following command in the Package Manager Console:

```powershell
Install-Package Accord.NET
```

Next, let's create a console application and write the following code:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Accord.Statistics.Models.NaiveBayes;
using Accord.Text;
using Accord.WkiCSV;

namespace TextClassificationApp
{
    class Program
    {
        static void Main(string[] args)
        {
            string dataPath = @"C:\path\to\your\data.csv";
            string[] categories = { "Sports", "Politics", "Entertainment" };

            var dataset = WkiCSVReader.ReadCSV<string[]>(dataPath);
            var featureExtractor = new CountVectorizer(true);
            var labels = dataset.Select(x => categories[Array.IndexOf(categories, x[0])]).ToArray();
            var trainingSet = featureExtractor.Transform(dataset.Skip(1).Take(500));
            var testSet = featureExtractor.Transform(new[] { dataset[0], dataset[501] });

            var naiveBayes = new NaiveBayes();
            naiveBayes.Learn(trainingSet, labels);
            var predictions = naiveBayes.Apply(testSet);

            Console.WriteLine("Accuracy: " + naiveBayes.Evaluate(predictions, labels)[2]);

            var newSentence = "The sports game was exciting.";
            var features = featureExtractor.ExtractFeatures(new[] { newSentence }, true);
            var prediction = naiveBayes.Apply(features);
            Console.WriteLine("Predicted category: " + categories[prediction[0].MaxValueIndex()]);
        }
    }
}
```

