                        break
                    }
                }

                if (!$found) {
                    write-host "access control entry with sid: $sid found in folder: $folder.fullname"
                }
            }
        }

        checkacl $folder.fullname
    }
}
```

3. Call the function with starting directory:

```powershell
checkacl c:\some_directory
```

in this script, `checkacl()` is a recursive function that takes a path as input and searches for all folders in it using `get-childitem`. For each folder, it gets the access control lists (ACLs) using `get-ace`, iter
